BEGIN;

-- ============================================================
-- Кружки. Однократный импорт стартового набора в пустую БД.
-- ============================================================

CREATE TABLE clubs (
    id            SERIAL PRIMARY KEY,
    name          TEXT,
    address       TEXT,
    latitude      NUMERIC(10, 6),
    longitude     NUMERIC(10, 6),
    subject       TEXT,
    status        TEXT,
    note          TEXT,
    source        TEXT
);


-- ============================================================
-- Источники
-- ============================================================

CREATE TABLE sources (
    id               SERIAL PRIMARY KEY,
    source_url       TEXT,
    example_places   TEXT,
    rows_count       INTEGER
);


COMMIT;
